using namespace std;

int findPlatform(vector<int>& arr, vector<int>& dep) {
    sort(arr.begin(), arr.end());
    sort(dep.begin(), dep.end());
    int i = 0, j = 0, occupied = 0, needed = 0;
    while (i < (int)arr.size()) {
        if (arr[i] <= dep[j]) {
            ++occupied;
            needed = max(needed, occupied);
            ++i;
        } else {
            --occupied;
            ++j;
        }
    }
    return needed;
}

