import java.util.Arrays;

class Solution {
    public int findPlatform(int[] arr, int[] dep) {
        Arrays.sort(arr);
        Arrays.sort(dep);
        int i = 0, j = 0, occupied = 0, needed = 0;
        while (i < arr.length) {
            if (arr[i] <= dep[j]) {
                ++occupied;
                needed = Math.max(needed, occupied);
                ++i;
            } else {
                --occupied;
                ++j;
            }
        }
        return needed;
    }
}
